INSERT INTO `career_goals` (`id`, `user_id`, `aspiration`, `specific_goal`, `measurable_criteria`, `achievable_steps`, `realistic_assessment`, `time_bound`, `current_skills`, `target_skills`, `progress_percentage`, `status`, `created_at`, `updated_at`) VALUES
(1, 2, 'Transition from PHP Developer to Java Developer', 'Gain proficiency in Java and secure a Java Developer position', '[\"Complete Java fundamentals course\",\"Build a Java web application using Spring Boot\",\"Solve 20 algorithmic problems using Java\"]', '[\"Enroll in a Java course within a week\",\"Start building the web application within 6 weeks\",\"Practice coding problems weekly for a month\"]', 'With a solid foundation in PHP and experience in web development, transitioning to Java is feasible with dedicated learning and practice.', 'Achieve these goals within 3 months', '[\"PHP\",\"MySQL\",\"JavaScript\"]', '[\"Java fundamentals\",\"JVM knowledge\",\"Data structures and algorithms\",\"Spring Boot\",\"JUnit\"]', 30, 'active', '2026-04-09 05:13:18', '2026-05-15 16:51:43'),
(2, 14, 'Become a Software Engineer', 'Transition into a Full Stack Software Engineer role within the tech industry', '[\"Complete 3 coding projects\",\"Attend 4 tech meetups\",\"Apply to 10 job openings\"]', '[\"Learn Git and version control\",\"Develop a project using Node.js and React\",\"Enhance understanding of RESTful APIs\"]', 'With my current skills in PHP, MySQL, and JavaScript, I have a solid foundation to build upon and can realistically learn new skills within a structured plan.', 'Achieve the goal within 6 months', '[\"PHP\",\"MySQL\",\"JavaScript\",\"ReactJS\",\"HTML\",\"Bootstrap\",\"AJAX\",\"jQuery\",\"Excel\"]', '[\"Node.js\",\"Git\",\"RESTful APIs\",\"MongoDB\",\"Agile methodologies\"]', 15, 'active', '2026-04-29 08:24:19', '2026-04-29 08:24:52'),
(3, 2, 'Transition to a Java Developer role', 'Enroll in a Java course within a week', '[\"Course completion certificate\",\"Completion of at least 5 coding exercises\"]', '[\"Research and select a suitable Java course\",\"Enroll in the chosen course\",\"Set a weekly study schedule\"]', 'The transition is realistic as I have a background in PHP and basic programming skills that will help me learn Java.', 'Enroll within 1 week from today', '[\"PHP\",\"MySQL\",\"JavaScript\"]', '[\"Java\",\"Spring Framework\",\"Object-Oriented Programming\"]', 0, 'active', '2026-05-15 11:34:25', '2026-05-15 11:34:25'),
(4, 2, 'Become proficient in Python programming and transition into a software development role.', 'Enroll in a Python course within a week and complete it in 4 weeks.', '[\"Complete course modules weekly\",\"Build 2 small projects by the end of the course\"]', '[\"Research and enroll in a Python course\",\"Set up Python development environment\",\"Complete first module within the first week\"]', 'Given my background in programming and familiarity with concepts, transitioning to Python is manageable with a structured approach.', 'Enroll in a course within 1 week and complete it within 4 weeks.', '[\"Core PHP\",\"MySQL\",\"jQuery\"]', '[\"Python\",\"Flask\",\"Data Structures\"]', 30, 'active', '2026-05-18 15:58:12', '2026-05-26 15:14:43'),
(5, 38, 'Transition to a Full-Stack Developer role', 'Complete a full-stack web application project using the MERN stack and Python', '[\"Project completed\",\"Course completed\"]', '[\"Identify target role by researching job descriptions\",\"Complete an online course on Docker within one month\",\"Develop and deploy a full-stack web application within three months\"]', 'I have a foundation in the MERN stack and Python, making it feasible to build new skills and complete a project within this timeline.', 'Project to be completed in three months; course to be completed in one month', '[\"JavaScript\",\"Node.js\",\"React\",\"MongoDB\",\"Python\"]', '[\"Docker\",\"AWS\",\"Express.js\"]', 10, 'active', '2026-05-23 09:54:36', '2026-05-23 09:54:46'),
(6, 58, 'Become a Software Engineer', 'Secure an entry-level software engineering position within the next 6 months', '[\"Complete 3 coding projects\",\"Pass 10 coding challenges on LeetCode\",\"Attend 5 networking events\"]', '[\"Learn Python in depth through online courses\",\"Practice data structures and algorithms for 30 minutes daily\",\"Build a personal website using HTML, CSS, and JavaScript\"]', 'This is realistic as I have a basic understanding of programming and can dedicate time daily to learning and practicing.', 'Achieve this goal within the next 6 months', '[\"Basics of C\",\"Basics of Python\",\"HTML\"]', '[\"Proficient in Python\",\"Data structures and algorithms\",\"CSS\",\"JavaScript\",\"Git\"]', 0, 'active', '2026-06-18 17:20:43', '2026-06-18 17:56:03');
